static int radius(const Obj*o){Obj copy=*o;ndraw=0;if(o->type==4)draw_stage_boss(fb,&copy,o->x/Q,o->y/Q);else if(o->type<5)pc_enemy_sprite(o->type==0?1:o->type+5,&copy,o->x/Q,o->y/Q);else draw_new_enemy(fb,&copy,o->x/Q,o->y/Q);float r=0;static const int wh[8][2]={{23,24},{30,34},{24,28},{24,28},{22,25},{26,30},{52,64},{24,36}};for(int i=0;i<ndraw;i++){Draw*d=draws+i;float w,h;if(d->n>=137){w=wh[d->n-137][0];h=wh[d->n-137][1];}else{w=modernSprites[d->n].w;h=modernSprites[d->n].h;}float size=hypotf(w,h)*.5f*(d->scale>0?d->scale:1);if(size>r)r=size;}return (int)ceilf(r);}
static int outside(int x,int y,int r){for(int dy=-r;dy<=r;dy+=3){float rx=sqrtf(fmaxf(0,r*r-dy*dy));int yy=y+dy,l=tunnel_left(yy),rr=tunnel_right(yy),il,ir;if(x-rx<l||x+rx>rr||(tunnel_island(yy,&il,&ir)&&x+rx>il&&x-rx<ir))return 1;}return 0;}
static void scene(int m,int section){headless=1;selectedShip=0;configuredLevel=1;game_reset();g.mode=1;g.fx=0;g.wave=m;ex.section=section;ex.phase=ex.oldPhase=mission_phase(m);ex.intro=ex.travel=ex.entryY=0;ex.phaseAge=100;ex.rearSpawned=1;ex.options=ex.optionsOn=0;g.clock=-100000;g.groups=0;g.shield=100000;environment_enter();}
int main(void){int contexts[6][2]={{2,1},{2,2},{3,2},{3,4},{4,5},{5,7}},samples=0,bad=0,spawnBad=0,hazardBad=0,hazardSamples=0;puts("CAVERN real movement / rendered hull radius / immunity isolates geometry only");for(int c=0;c<6;c++){int cbad=0,csamples=0;for(int type=0;type<29;type++){if(type==9||type==23||type==24)continue;scene(contexts[c][0],contexts[c][1]);if(type==4){ex.bossSpawned=1;ex.encounterTier=1;Obj*o=g.enemies;*o=(Obj){.on=1,.type=4,.variant=12,.hp=100,.base=300,.phase=3,.power=512,.x=160*Q,.y=95*Q,.age=200};}else if(type==22)rear_group();else group(type,0);for(int i=0;i<MAXE;i++)if(g.enemies[i].on){Obj*o=g.enemies+i;int r=radius(o);spawnBad+=outside(o->x/Q,o->y/Q,r);}for(int t=0;t<240;t++){g.shield=100000;game_step(0,0);for(int i=0;i<MAXE;i++){Obj*o=g.enemies+i;if(!o->on)continue;int r=radius(o);csamples++;cbad+=outside(o->x/Q,o->y/Q,r);}for(int i=0;i<32;i++){EnvironmentHazard*h=ex.env.hazards+i;if(!h->on)continue;hazardSamples++;hazardBad+=outside(h->x/Q,h->y/Q,h->type==12?24:h->type>=20?21:h->type==11?17:h->type==14?23:(int)ceilf(h->r*1.42f));}}}samples+=csamples;bad+=cbad;printf("CONTEXT %d %d %d %d\n",contexts[c][0],contexts[c][1],csamples,cbad);}printf("TOTAL %d %d %d %d %d\n",spawnBad,samples,bad,hazardSamples,hazardBad);return spawnBad||bad||hazardBad?1:0;}
